      const terminal = ['malformed-consent', 'malformed-profile', 'malformed-reflex', 'wrong-owner', 'missing-identity', 'forward', 'falsy-forward', 'null-state', 'falsy-state', 'undefined-read', 'read-error'].includes(mode);
